import test from 'node:test';
import assert from 'node:assert/strict';
import { apply } from '../index.js';

// These requests must fail before launch, so no real OS application is opened.
// The release entry is regenerated by the integration build before this suite.
test('authenticated API accepts local file actions and validates paths and sessions', async () => {
  let route;
  const cleanups = [];
  await apply({
    connection: { fetch: { register: value => { route = value; return () => {}; } } },
    agents: { get: () => undefined },
    workspaceRegistry: { list: () => [] },
    storageDomain: { open: async spec => {
      let state = spec.global.initial;
      return { global: { get: () => state, set: async value => { state = value; } }, close() {} };
    } },
    tools: { register() {} }, commands: { register() {} }, systemPrompt: { context() {} },
    on() {}, effect: fn => cleanups.push(fn()),
  });
  try {
    assert.equal(route.path, '/api/dsh-workdock');
    const request = async args => {
      const response = await route.fetch(new Request('http://localhost/api/dsh-workdock', {
        method: 'POST', body: JSON.stringify({ sessionId: 'not-an-active-agent', args }),
      }));
      return { status: response.status, body: await response.json() };
    };
    for (const action of ['open_file', 'reveal_file']) {
      const relative = await request({ action, path: 'relative.txt' });
      assert.equal(relative.status, 400);
      assert.equal(relative.body.ok, false);
      assert.match(relative.body.error, /相对路径需要活动聊天会话/);
      for (const path of [undefined, '', 'https://example.com/report.txt', 'bad\0name']) {
        const invalid = await request({ action, path });
        assert.equal(invalid.status, 400);
        assert.equal(invalid.body.ok, false);
      }
    }
    const existing = await request({ action: 'list' });
    assert.equal(existing.status, 200);
    assert.deepEqual(existing.body.value.projects, []);
  } finally { for (const cleanup of cleanups) await cleanup?.(); }
});
